with a as(select * from public.authors where open_library_id=any(array['OL236174A','OL39329A','OL28165A','OL30522A','OL20371A','OL48139A','OL81831A','OL16016329A','OL45364A','OL40784A','OL23425A','OL27048A','OL1448154A','OL20985A']::text[])),w as(select * from public.works where open_library_id=any(array['OL106837W','OL627084W','OL927199W','OL44532018W','OL1966501W','OL554723W','OL17116910W','OL77011W','OL41256W','OL18342W','OL14963876W','OL158630W','OL462936W','OL16342070W','OL14860198W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9780679601609','9780679410430','9781887368094','9789000398034','9780582446946','9789022539323','9789049205430','9789022986790','9789022996621','9789044502985','9789024556595','9789044508772','9789022531259','9789029575379','9789027466976','9789060571552','9789025467418','9789060574225','9789025305567']::text[]) or open_library_edition_id=any(array['OL25417175M','OL7699607M','OL25429595M','OL1744092M','OL57624515M','OL8708151M','OL60810273M','OL25696571M','OL16540544M','OL27276228M','OL61440168M','OL32776514M','OL47132353M','OL19156411M','OL32760422M','OL34367865M','OL42904946M','OL35327499M','OL47264445M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987152001 and 987152999),'editions',(select count(*) from public.editions where id between 987252001 and 987252999),'authors',(select count(*) from public.authors where id between 987352001 and 987352999))) as preflight;
